import { createContext, useCallback, useContext, useEffect, useState } from 'react'

export type Theme = 'dark' | 'light'
const STORAGE_KEY = 'scenelab-theme'

function getPreferredTheme(): Theme {
  if (typeof window === 'undefined') return 'dark'
  try {
    const stored = localStorage.getItem(STORAGE_KEY)
    if (stored === 'dark' || stored === 'light') return stored
  } catch {
    // ignore storage errors
  }
  try {
    if (window.matchMedia('(prefers-color-scheme: light)').matches) return 'light'
  } catch {
    // ignore
  }
  return 'dark'
}

function applyTheme(theme: Theme): void {
  try {
    document.documentElement.setAttribute('data-theme', theme)
    // color-scheme hints native controls
    document.documentElement.style.colorScheme = theme
  } catch {
    // ignore
  }
}

interface ThemeContextValue {
  theme: Theme
  toggleTheme: () => void
  setTheme: (t: Theme) => void
}

const ThemeContext = createContext<ThemeContextValue>({
  theme: 'dark',
  toggleTheme: () => {},
  setTheme: () => {},
})

export function ThemeProvider({ children }: { children: React.ReactNode }): JSX.Element {
  const [theme, setThemeState] = useState<Theme>(() => getPreferredTheme())

  useEffect(() => {
    applyTheme(theme)
    try {
      localStorage.setItem(STORAGE_KEY, theme)
    } catch {
      // ignore
    }
  }, [theme])

  // Follow system preference only when user has no explicit choice
  useEffect(() => {
    let mql: MediaQueryList | null = null
    try {
      mql = window.matchMedia('(prefers-color-scheme: light)')
    } catch {
      return
    }
    if (!mql) return
    const handler = (e: MediaQueryListEvent): void => {
      try {
        const stored = localStorage.getItem(STORAGE_KEY)
        if (stored) return
      } catch {
        return
      }
      setThemeState(e.matches ? 'light' : 'dark')
    }
    // modern browsers: addEventListener, fallback to addListener
    if (mql.addEventListener) mql.addEventListener('change', handler)
    else (mql as unknown as { addListener: (fn: (e: MediaQueryListEvent) => void) => void }).addListener(handler)
    return () => {
      if (!mql) return
      if (mql.removeEventListener) mql.removeEventListener('change', handler)
      else (mql as unknown as { removeListener: (fn: (e: MediaQueryListEvent) => void) => void }).removeListener(handler)
    }
  }, [])

  const toggleTheme = useCallback(() => {
    setThemeState((prev) => (prev === 'dark' ? 'light' : 'dark'))
  }, [])

  const setTheme = useCallback((t: Theme) => setThemeState(t), [])

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme, setTheme }}>
      {children}
    </ThemeContext.Provider>
  )
}

export function useTheme(): ThemeContextValue {
  return useContext(ThemeContext)
}

