import { chromium } from 'playwright';

const BASE = 'http://127.0.0.1:4173/';

function contrastRatio(l1, l2) {
  // relative luminance
  const lum = (c) => {
    const srgb = c / 255;
    return srgb <= 0.03928 ? srgb / 12.92 : Math.pow((srgb + 0.055) / 1.055, 2.4);
  };
  const L = (r,g,b) => 0.2126*lum(r)+0.7152*lum(g)+0.0722*lum(b);
  // parse hex or rgb
  const parse = (str) => {
    if (!str) return null;
    str=str.trim();
    let m;
    if (m=str.match(/^#([0-9a-f]{3})$/i)) {
      const h=m[1];
      return [parseInt(h[0]+h[0],16),parseInt(h[1]+h[1],16),parseInt(h[2]+h[2],16)];
    }
    if (m=str.match(/^#([0-9a-f]{6})$/i)) {
      const h=m[1];
      return [parseInt(h.slice(0,2),16),parseInt(h.slice(2,4),16),parseInt(h.slice(4,6),16)];
    }
    if (m=str.match(/^rgb\((\d+),\s*(\d+),\s*(\d+)\)/)) return [parseInt(m[1]),parseInt(m[2]),parseInt(m[3])];
    if (m=str.match(/^rgba\((\d+),\s*(\d+),\s*(\d+),\s*([\d.]+)\)/)) return [parseInt(m[1]),parseInt(m[2]),parseInt(m[3])];
    // for var fallback, try computed style via browser
    return null;
  };
  const a=parse(l1), b=parse(l2);
  if(!a||!b) return null;
  const La=L(...a), Lb=L(...b);
  const lmax=Math.max(La,Lb), lmin=Math.min(La,Lb);
  return (lmax+0.05)/(lmin+0.05);
}

